1487	/// Deactivate the source account (no `deleteAfter`). Last cutover step — runs only
1488	/// after the destination is active AND its sovereign session is durably persisted,
1489	/// so a wallet crash can never strand the account credential-less.
1490	async fn deactivate_source_account(source_client: &OAuthClient) -> Result<(), MigrationError> {
1491	    tracing::debug!("finalizing migration: deactivating source account");
1492	    crate::pds_client::deactivate_account(source_client, None)
1493	        .await
1494	        .map_err(|e| {
1495	            tracing::error!(error = %e, "deactivate_account failed");
1496	            MigrationError::DeactivationFailed {
1497	                message: format!("failed to deactivate source account: {}", e),
1498	            }
1499	        })
1500	}
1501	
1502	/// Map a sovereign-login failure onto the retryable pre-cutover migration errors.
1503	/// A Keychain write failure is a *persistence* failure (the mint succeeded but could
1504	/// not be saved); everything else is a *login* failure. Both keep the source active.
1505	fn map_sovereign_error(error: crate::sovereign_session::SovereignLoginError) -> MigrationError {
1506	    use crate::sovereign_session::SovereignLoginError as E;
1507	    match error {
1508	        E::KeychainFailure { message } => MigrationError::SessionPersistFailed { message },
1509	        other => MigrationError::SovereignLoginFailed {
1510	            message: other.to_string(),
1511	        },
1512	    }
1513	}
1514	
1515	/// Ensure the migrated DID has a durably persisted destination sovereign session,
1516	/// minting one with the DID's current rotation key if needed.
1517	///
1518	/// Idempotency (the resume seam): if a persisted record whose *refresh* token is
1519	/// still unexpired already exists, this returns `Ok` without signing anything — a
1520	/// resumed finalize must not re-mint (and thus must not require a fresh device-key
1521	/// signature) when a durable credential already exists. Only a missing or
1522	/// refresh-expired record triggers a new device-signed mint via
1523	/// `sovereign_login_impl`, which discovers plc.directory's current rotation set and
1524	/// the hosted account, proves control, and atomically replaces the token record.
1525	async fn ensure_sovereign_session_persisted(
1526	    pds_client: &crate::pds_client::PdsClient,
1527	    store: &crate::identity_store::IdentityStore,
1528	    did: &str,
1529	    now: i64,
1530	    nonce: &str,
1531	) -> Result<(), MigrationError> {
1532	    if let Some(record) =
1533	        store
1534	            .load_oauth_tokens(did)
1535	            .map_err(|e| MigrationError::SessionPersistFailed {
1536	                message: e.to_string(),
1537	            })?
1538	    {
1539	        if record
1540	            .refresh_expires_at
1541	            .is_some_and(|exp| (exp as i64) > now)
1542	        {
1543	            tracing::info!(did = %did, "sovereign session already persisted; skipping re-mint");
1544	            return Ok(());
1545	        }
1546	    }
1547	
1548	    crate::sovereign_session::sovereign_login_impl(pds_client, store, did, now, nonce)
1549	        .await
1550	        .map(|_| ())
1551	        .map_err(map_sovereign_error)
1552	}
1553	
1554	/// Ensure a migrated did:web identity has a durably persisted destination session.
1555	///
1556	/// A did:web account has no PLC rotation keys, so the sovereign mint
1557	/// (`/v1/sessions/sovereign`, rotation-key-signed) is unavailable to it. The
1558	/// Bearer session the destination issued during the migration is the account's
1559	/// only credential — this persists that pair to the Keychain so it survives the
1560	/// app process, and it must succeed *before* the source is deactivated.
1561	///
1562	/// Idempotency mirrors `ensure_sovereign_session_persisted`: an existing record
1563	/// whose refresh token is still unexpired is left untouched, so a resumed
1564	/// finalize never clobbers a durable credential with a possibly-staler one.
1565	async fn ensure_didweb_session_persisted(
1566	    store: &crate::identity_store::IdentityStore,
1567	    did: &str,
1568	    dest_client: &OAuthClient,
1569	    dest_pds_url: &str,
1570	    dest_server_did: &str,
1571	    now: i64,
1572	) -> Result<(), MigrationError> {
1573	    if let Some(record) =
1574	        store
1575	            .load_oauth_tokens(did)
1576	            .map_err(|e| MigrationError::SessionPersistFailed {
1577	                message: e.to_string(),
1578	            })?
1579	    {
1580	        if record
1581	            .refresh_expires_at
1582	            .is_some_and(|exp| (exp as i64) > now)
1583	        {
1584	            tracing::info!(did = %did, "did:web session already persisted; skipping");
1585	            return Ok(());
1586	        }
1587	    }
1588	
1589	    let (access_jwt, refresh_jwt) = dest_client.session_tokens();
1590	    let access_claims = crate::sovereign_session::bearer_jwt_claims(&access_jwt).ok_or(
1591	        MigrationError::SessionPersistFailed {
1592	            message: "destination access token is not a readable JWT".into(),
1593	        },
1594	    )?;
1595	    let refresh_claims = crate::sovereign_session::bearer_jwt_claims(&refresh_jwt).ok_or(
1596	        MigrationError::SessionPersistFailed {
1597	            message: "destination refresh token is not a readable JWT".into(),
1598	        },
1599	    )?;
1600	    for claims in [&access_claims, &refresh_claims] {
1601	        if claims.sub != did {
1602	            return Err(MigrationError::SessionPersistFailed {
1603	                message: "destination session subject does not match the migrated DID".into(),
1604	            });
1605	        }
1606	        if !crate::sovereign_session::audience_matches_server(
1607	            &claims.aud,
1608	            dest_server_did,
1609	            dest_pds_url,
1610	        ) {
1611	            return Err(MigrationError::SessionPersistFailed {
1612	                message: "destination session audience does not match the destination PDS".into(),
1613	            });
1614	        }
1615	    }
1616	
1617	    let record = crate::identity_store::SovereignTokenRecord {
1618	        version: crate::identity_store::SovereignTokenRecord::VERSION,
1619	        access_jwt,
1620	        refresh_jwt,
1621	        pds_url: dest_pds_url.trim_end_matches('/').to_string(),
1622	        server_did: dest_server_did.to_string(),
1623	        access_expires_at: Some(access_claims.exp),
1624	        refresh_expires_at: Some(refresh_claims.exp),
1625	        stored_at: u64::try_from(now).map_err(|_| MigrationError::SessionPersistFailed {
1626	            message: "system clock is before the Unix epoch".into(),
1627	        })?,
1628	    };
1629	    store
1630	        .store_oauth_tokens(did, &record)
1631	        .map_err(|e| MigrationError::SessionPersistFailed {
1632	            message: e.to_string(),
1633	        })
1634	}
1635	
1636	/// Tauri command: run the safe cutover — activate the destination, mint + persist its
1637	/// sovereign session, deactivate the source, then advance to Finalized.
1638	///
1639	/// Gate: ensure_phase_did(..., IdentityArmed) → defense-in-depth: migration_state
1640	/// must be cleared (None) to prove the identity op was submitted; if Some → MIGRATION_NOT_READY.
1641	/// The sovereign-session mint runs against the DID's *current* PLC rotation set (the identity op
1642	/// has already landed) using a fresh device-key proof; the frontend re-gates biometric before
1643	/// every finalize invocation, so a resumed attempt obtains fresh authorization before that
1644	/// signature (and the idempotent skip means an already-persisted session signs nothing at all).
1645	#[tauri::command]
1646	pub async fn finalize_migration(
1647	    state: tauri::State<'_, crate::oauth::AppState>,
1648	    did: String,
1649	) -> Result<(), MigrationError> {
1650	    tracing::info!(did = %did, "finalize_migration: activate → sovereign session → deactivate");
1651	
1652	    // Proof material for the sovereign-session mint (imperative shell: clock + RNG).
1653	    let now = crate::sovereign_session::unix_timestamp().map_err(map_sovereign_error)?;
1654	
1655	    // A did:web identity has no PLC rotation keys, so the sovereign mint is impossible for it;
1656	    // persist the migration-issued destination Bearer session instead. Snapshot the destination
1657	    // coordinates up front — the closure runs after `finalize_migration_core`'s own phase/client
1658	    // gates, so a missing client here surfaces through those gates, never through the closure.
1659	    if did.starts_with("did:web:") {
1660	        let (dest_client, dest_pds_url, dest_server_did) = {
1661	            let orchestration = state.orchestration_state.lock().await;
1662	            match orchestration.as_ref() {
1663	                Some(mig) => (
1664	                    mig.dest_client.clone(),
1665	                    mig.dest_pds_url.clone(),
1666	                    mig.dest_did.clone(),
1667	                ),
1668	                None => (None, String::new(), String::new()),
1669	            }
1670	        };
1671	        let session_did = did.clone();
1672	        return finalize_migration_core(
1673	            &state.orchestration_state,
1674	            &state.migration_state,
1675	            &did,
1676	            || async move {
1677	                let dest_client =
1678	                    dest_client.ok_or_else(|| MigrationError::AccountCreationFailed {
1679	                        message: "destination client not authenticated".into(),
1680	                    })?;
1681	                ensure_didweb_session_persisted(
1682	                    &crate::identity_store::IdentityStore,
1683	                    &session_did,
1684	                    &dest_client,
1685	                    &dest_pds_url,
1686	                    &dest_server_did,
1687	                    now,
1688	                )
1689	                .await
1690	            },
1691	        )
1692	        .await;
1693	    }
1694	
1695	    let nonce = crate::sovereign_session::fresh_nonce();
1696	    let pds_client = state.pds_client();
1697	    let session_did = did.clone();
1698	
1699	    finalize_migration_core(
1700	        &state.orchestration_state,
1701	        &state.migration_state,
1702	        &did,
1703	        || async move {
1704	            ensure_sovereign_session_persisted(
1705	                pds_client,
1706	                &crate::identity_store::IdentityStore,
1707	                &session_did,
1708	                now,
1709	                &nonce,
1710	            )
1711	            .await
1712	        },
1713	    )
1714	    .await
1715	}
1716	
1717	/// Core of `finalize_migration`, parameterized over the two mutexes and an injected
1718	/// `ensure_session` step so its gating, ordering, and phase advance are unit-testable without a
1719	/// Tauri `State`, a Keychain, or a live PDS. Gate at IdentityArmed; require the migrate
1720	/// `migration_state` cleared (== None, proving `submit_migration_op_cmd` ran); then run the cutover
1721	/// in strict order — **activate destination → ensure sovereign session persisted → deactivate
1722	/// source** — and advance to `Finalized`.
1723	///
1724	/// The ordering is the whole point: `ensure_session` (mint + Keychain persist) runs *after*
1725	/// activation and *before* deactivation, so a sovereign-login or persistence failure aborts the
